import{_ as l,a0 as p,w as d,s as a,I as i,x as t,a1 as o,A as r,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"怎样在CentOS 7.0上安装和配置VNC服务器 | LCTT x X-CMD","titleTemplate":false,"description":"怎样在CentOS 7.0上安装和配置VNC服务器 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在CentOS 7.0上安装和配置VNC服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在CentOS 7.0上安装和配置VNC服务器 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0","title":"怎样在CentOS 7.0上安装和配置VNC服务器","tag":"201504","desc":""},"relativePath":"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0.md","filePath":"[post].md"}'),c={name:"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0.md"};function u(C,e,m,g,v,V){const n=p("Link");return d(),a("div",null,[e[26]||(e[26]=i("h1",{id:"怎样在centos-7-0上安装和配置vnc服务器",tabindex:"-1"},[t("怎样在CentOS 7.0上安装和配置VNC服务器 "),i("a",{class:"header-anchor",href:"#怎样在centos-7-0上安装和配置vnc服务器","aria-label":"Permalink to “怎样在CentOS 7.0上安装和配置VNC服务器”"},"​")],-1)),i("p",null,[e[2]||(e[2]=t("这是一个关于怎样在你的 CentOS 7 上安装配置 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:r(()=>[...e[0]||(e[0]=[t("VNC",-1)])]),_:1}),e[3]||(e[3]=t(" 服务的教程。当然这个教程也适合 RHEL 7 。在这个教程里，我们将学习什么是 VNC 以及怎样在 CentOS 7 上安装配置 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:r(()=>[...e[1]||(e[1]=[t("VNC 服务器",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))]),e[27]||(e[27]=s('<p>我们都知道，作为一个系统管理员，大多数时间是通过网络管理服务器的。在管理服务器的过程中很少会用到图形界面，多数情况下我们只是用 SSH 来完成我们的管理任务。在这篇文章里，我们将配置 VNC 来提供一个连接我们 CentOS 7 服务器的方法。VNC 允许我们开启一个远程图形会话来连接我们的服务器，这样我们就可以通过网络远程访问服务器的图形界面了。</p><p>VNC 服务器是一个自由开源软件，它可以让用户可以远程访问服务器的桌面环境。另外连接 VNC 服务器需要使用 VNC viewer 这个客户端。</p><p>** 一些 VNC 服务器的优点：**</p><ul><li>远程的图形管理方式让工作变得简单方便。</li><li>剪贴板可以在 CentOS 服务器主机和 VNC 客户端机器之间共享。</li><li>CentOS 服务器上也可以安装图形工具，让管理能力变得更强大。</li><li>只要安装了 VNC 客户端，通过任何操作系统都可以管理 CentOS 服务器了。</li><li>比 ssh 图形转发和 RDP 连接更可靠。</li></ul><p>那么，让我们开始安装 VNC 服务器之旅吧。我们需要按照下面的步骤一步一步来搭建一个可用的 VNC。</p><p>首先，我们需要一个可用的桌面环境（X-Window），如果没有的话要先安装一个。</p><p><strong>注意：以下命令必须以 root 权限运行。要切换到 root ，请在终端下运行“sudo -s”，当然不包括双引号（“”）</strong></p><h3 id="_1-安装-x-window" tabindex="-1">1. 安装 X-Window <a class="header-anchor" href="#_1-安装-x-window" aria-label="Permalink to “1. 安装 X-Window”">​</a></h3>',8)),i("p",null,[e[6]||(e[6]=t("首先我们需要安装 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/X_Window_System"},{default:r(()=>[...e[5]||(e[5]=[t("X-Window",-1)])]),_:1}),e[7]||(e[7]=t("，在终端中运行下面的命令，安装会花费一点时间。",-1))]),e[28]||(e[28]=s(`<pre><code># yum check-update
# yum groupinstall &quot;X Window System&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/installing-x-windows.png" alt="installing x windows"></p><pre><code>#yum install gnome-classic-session gnome-terminal nautilus-open-terminal control-center liberation-mono-fonts
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/gnome-classic-session-install.png" alt="install gnome classic session"></p><pre><code>### 设置默认启动图形界面
# unlink /etc/systemd/system/default.target
# ln -sf /lib/systemd/system/graphical.target /etc/systemd/system/default.target
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-graphics.png" alt="configuring graphics"></p><pre><code># reboot
</code></pre><p>在服务器重启之后，我们就有了一个工作着的 CentOS 7 桌面环境了。</p><p>现在，我们要在服务器上安装 VNC 服务器了。</p><h3 id="_2-安装-vnc-服务器" tabindex="-1">2. 安装 VNC 服务器 <a class="header-anchor" href="#_2-安装-vnc-服务器" aria-label="Permalink to “2. 安装 VNC 服务器”">​</a></h3><p>现在要在我们的 CentOS 7 上安装 VNC 服务器了。我们需要执行下面的命令。</p><pre><code># yum install tigervnc-server -y
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/install-tigervnc.png" alt="vnc server"></p><h3 id="_3-配置-vnc" tabindex="-1">3. 配置 VNC <a class="header-anchor" href="#_3-配置-vnc" aria-label="Permalink to “3. 配置 VNC”">​</a></h3><p>然后，我们需要在 <code>/etc/systemd/system/</code> 目录里创建一个配置文件。我们可以将 <code>/lib/systemd/sytem/vncserver@.service</code> 拷贝一份配置文件范例过来。</p><pre><code># cp /lib/systemd/system/vncserver@.service /etc/systemd/system/vncserver@:1.service
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/copying-configuration.png" alt="copying vnc server configuration"></p><p>接着我们用自己最喜欢的编辑器（这儿我们用的 <strong>nano</strong> ）打开 <code>/etc/systemd/system/vncserver@:1.service</code> ，找到下面这几行，用自己的用户名替换掉 <code>&lt;USER&gt;</code> 。举例来说，我的用户名是 linoxide 所以我用 linoxide 来替换掉 <code>&lt;USER&gt;</code> ：</p><pre><code>ExecStart=/sbin/runuser -l &lt;USER&gt; -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/home/&lt;USER&gt;/.vnc/%H%i.pid
</code></pre><p>替换成</p><pre><code>ExecStart=/sbin/runuser -l linoxide -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/home/linoxide/.vnc/%H%i.pid
</code></pre><p>如果是 root 用户则</p><pre><code>ExecStart=/sbin/runuser -l root -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/root/.vnc/%H%i.pid
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-user.png" alt="configuring user"></p><p>好了，下面重启 systemd 。</p><pre><code># systemctl daemon-reload
</code></pre><p>最后还要设置一下用户的 VNC 密码。要设置某个用户的密码，必须要有能通过 sudo 切换到用户的权限，这里我用 linoxide 的权限，执行“<code>su linoxide</code>”就可以了。</p><pre><code># su linoxide
$ sudo vncpasswd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/vncpassword.png" alt="setting vnc password"></p><p><strong>确保你输入的密码多于6个字符</strong></p><h3 id="_4-开启服务" tabindex="-1">4. 开启服务 <a class="header-anchor" href="#_4-开启服务" aria-label="Permalink to “4. 开启服务”">​</a></h3><p>用下面的命令（永久地）开启服务：</p><pre><code>$ sudo systemctl enable vncserver@:1.service
</code></pre><p>启动服务。</p><pre><code>$ sudo systemctl start vncserver@:1.service
</code></pre><h3 id="_5-防火墙设置" tabindex="-1">5. 防火墙设置 <a class="header-anchor" href="#_5-防火墙设置" aria-label="Permalink to “5. 防火墙设置”">​</a></h3><p>我们需要配置防火墙来让 VNC 服务正常工作。</p><pre><code>$ sudo firewall-cmd --permanent --add-service vnc-server
$ sudo systemctl restart firewalld.service
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/allowing-firewalld.png" alt="allowing firewalld"></p><p>现在就可以用 IP 和端口号（LCTT 译注：例如 192.168.1.1:1 ，这里的端口不是服务器的端口，而是视 VNC 连接数的多少从1开始排序）来连接 VNC 服务器了。</p><h3 id="_6-用-vnc-客户端连接服务器" tabindex="-1">6. 用 VNC 客户端连接服务器 <a class="header-anchor" href="#_6-用-vnc-客户端连接服务器" aria-label="Permalink to “6. 用 VNC 客户端连接服务器”">​</a></h3><p>好了，现在已经完成了 VNC 服务器的安装了。要使用 VNC 连接服务器，我们还需要一个在本地计算机上安装的仅供连接远程计算机使用的 VNC 客户端。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/vncviewer.png" alt="remote access vncserver from vncviewer"></p>`,43)),i("p",null,[e[10]||(e[10]=t("你可以用像 ",-1)),o(n,{href:"http://www.tightvnc.com/"},{default:r(()=>[...e[8]||(e[8]=[t("Tightvnc viewer",-1)])]),_:1}),e[11]||(e[11]=t(" 和 ",-1)),o(n,{href:"https://www.realvnc.com/"},{default:r(()=>[...e[9]||(e[9]=[t("Realvnc viewer",-1)])]),_:1}),e[12]||(e[12]=t(" 的客户端来连接到服务器。",-1))]),e[29]||(e[29]=s(`<p>要用更多的用户连接，需要创建配置文件和端口，请回到第3步，添加一个新的用户和端口。你需要创建 <code>vncserver@:2.service</code> 并替换配置文件里的用户名和之后步骤里相应的文件名、端口号。<strong>请确保你登录 VNC 服务器用的是你之前配置 VNC 密码的时候使用的那个用户名</strong>。</p><p>VNC 服务本身使用的是5900端口。鉴于有不同的用户使用 VNC ，每个人的连接都会获得不同的端口。配置文件名里面的数字告诉 VNC 服务器把服务运行在5900的子端口上。在我们这个例子里，第一个 VNC 服务会运行在5901（5900 + 1）端口上，之后的依次增加，运行在5900 + x 号端口上。其中 x 是指之后用户的配置文件名 <code>vncserver@:x.service</code> 里面的 x 。</p><p>在建立连接之前，我们需要知道服务器的 IP 地址和端口。IP 地址是一台计算机在网络中的独特的识别号码。我的服务器的 IP 地址是96.126.120.92，VNC 用户端口是1。</p><p>执行下面的命令可以获得服务器的公网 IP 地址（LCTT 译注：如果你的服务器放在内网或使用动态地址的话，可以这样获得其公网 IP 地址）。</p><pre><code># curl -s checkip.dyndns.org|sed -e &#39;s/.*Current IP Address: //&#39; -e &#39;s/&lt;.*$//&#39;
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>好了，现在我们已经在运行 CentOS 7 / RHEL 7 的服务器上安装配置好了 VNC 服务器。VNC 是自由开源软件中最简单的一种能实现远程控制服务器的工具，也是一款优秀的 Teamviewer Remote Access 替代品。VNC 允许一个安装了 VNC 客户端的用户远程控制一台安装了 VNC 服务的服务器。下面还有一些经常使用的相关命令。好好玩！</p><h4 id="其他命令" tabindex="-1">其他命令： <a class="header-anchor" href="#其他命令" aria-label="Permalink to “其他命令：”">​</a></h4><ul><li><p>关闭 VNC 服务。</p><pre><code>  # systemctl stop vncserver@:1.service
</code></pre></li><li><p>禁止 VNC 服务开机启动。</p><pre><code>  # systemctl disable vncserver@:1.service
</code></pre></li><li><p>关闭防火墙。</p><pre><code>  # systemctl stop firewalld.service
</code></pre></li></ul><hr>`,10)),i("p",null,[e[14]||(e[14]=t("via: ",-1)),o(n,{href:"http://linoxide.com/linux-how-to/install-configure-vnc-server-centos-7-0/"},{default:r(()=>[...e[13]||(e[13]=[t("http://linoxide.com/linux-how-to/install-configure-vnc-server-centos-7-0/",-1)])]),_:1})]),i("p",null,[e[18]||(e[18]=t("作者：",-1)),o(n,{href:"http://linoxide.com/author/arunp/"},{default:r(()=>[...e[15]||(e[15]=[t("Arun Pyasi",-1)])]),_:1}),e[19]||(e[19]=t(" 译者：",-1)),o(n,{href:"https://github.com/boredivan"},{default:r(()=>[...e[16]||(e[16]=[t("boredivan",-1)])]),_:1}),e[20]||(e[20]=t(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[23]||(e[23]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...e[22]||(e[22]=[t("Linux中国",-1)])]),_:1}),e[25]||(e[25]=t(" 荣誉推出",-1))])])}const x=l(c,[["render",u]]);export{f as __pageData,x as default};
